{
  "name": "claude-mem-cursor",
  "version": "13.23.1",
  "description": "Persistent memory for Cursor. Hooks ingest tool use; MCP searches past sessions. Works with a local worker or a remote cmem.ai worker, and a local host-login observer or remote inference.",
  "author": { "name": "Alex Newman" },
  "homepage": "https://github.com/thedotmack/claude-mem",
  "repository": "https://github.com/thedotmack/claude-mem",
  "license": "Apache-2.0",
  "keywords": ["claude-mem", "memory", "cursor", "mcp", "cmem"],
  "category": "MCP",
  "skills": "./skills/",
  "hooks": "./hooks/hooks.json",
  "mcpServers": "./mcp.json",
  "variables": {
    "type": "object",
    "properties": {
      "CLAUDE_MEM_MCP_URL": {
        "type": "string",
        "title": "Remote MCP URL",
        "description": "Leave empty for a local worker (stdio). Set to https://cmem.ai/api/mcp (or your server) for remote."
      },
      "CLAUDE_MEM_MCP_TOKEN": {
        "type": "string",
        "title": "Remote MCP token",
        "description": "Bearer token for remote MCP. Unused for local worker."
      }
    },
    "required": []
  }
}

{
  "version": 1,
  "hooks": {
    "beforeSubmitPrompt": [
      { "command": "npx -y claude-mem hook cursor session-init" },
      { "command": "npx -y claude-mem hook cursor context" }
    ],
    "afterMCPExecution": [
      { "command": "npx -y claude-mem hook cursor observation" }
    ],
    "afterShellExecution": [
      { "command": "npx -y claude-mem hook cursor observation" }
    ],
    "afterFileEdit": [
      { "command": "npx -y claude-mem hook cursor file-edit" }
    ],
    "stop": [
      { "command": "npx -y claude-mem hook cursor summarize" }
    ]
  }
}
